SourceCode.Declaration:
internal class UPSPriceTermEnableDisable extends RunBase
{
    private UPSCheckEnableDisable operationType;
    private UPSPriceTermJournalTable journalTable;
    private FormDataSource journalTable_ds;
    private FormDataSource journalTrans_ds;
    private UPSIEnableDisableForm caller;

    private boolean isValid = true;

}

Method.Source:
public ClassDescription caption()
{
    if (operationType == UPSCheckEnableDisable::Check)
    {
        return strFmt("@UnifiedPricingService:UPSPriceTermEnableDisable_Caption_Check", this.journalTable.AgreementId);
    }
    else if (operationType == UPSCheckEnableDisable::Disable)
    {
        return strFmt("@UnifiedPricingService:UPSPriceTermEnableDisable_Caption_Disable", this.journalTable.AgreementId);
    }
    else
    {
        return strFmt("@UnifiedPricingService:UPSPriceTermEnableDisable_Caption_Enable", this.journalTable.AgreementId);
    }
}

public static void main(Args args)
{
    UPSPriceTermEnableDisable enableDisable = UPSPriceTermEnableDisable::newFromArgs(args);
    if (enableDisable.prompt())
    {
        enableDisable.runOperation();
    }
}

public static UPSPriceTermEnableDisable newFromArgs(Args args)
{
    UPSPriceTermJournalTable journalTable = args.record();
    UPSCheckEnableDisable operationType = args.parmEnum();
    return new UPSPriceTermEnableDisable(journalTable, operationType, args.caller());
}

public void new(UPSPriceTermJournalTable _journalTable, UPSCheckEnableDisable _operationType, UPSIEnableDisableForm _caller = null)
{
    this.journalTable = _journalTable;
    this.operationType = _operationType;
    this.caller =_caller;
}

public final void run()
{
    boolean ret;
    switch (this.operationType)
    {
        case UPSCheckEnableDisable::Check:
            ret = this.checkJournal();
            if (ret)
            {
                Info(strFmt("@UnifiedPricingService:UPSPriceTermEnableDisable_Check_Succeed", journalTable.AgreementId));
            }
            else
            {
                warning(strFmt("@UnifiedPricingService:UPSPriceTermEnableDisable_Check_Fail", journalTable.AgreementId));
            }
            break;
        case UPSCheckEnableDisable::Enable:
            ret = this.checkJournal();
            if (ret)
            {
                this.enableJournal();
                Info(strFmt("@UnifiedPricingService:UPSPriceTermEnableDisable_Enabled", journalTable.AgreementId));
            }
            else
            {
                warning(strFmt("@UnifiedPricingService:UPSPriceTermEnableDisable_Check_Fail", journalTable.AgreementId));
            }
            break;
        case UPSCheckEnableDisable::Disable:
            this.disableJournal();
            break;
    }
}

protected boolean checkJournal()
{
    boolean ret = true;

    ret = ret && journalTable.validateWrite();

    UPSPriceTermJournalTrans journalTrans;
    while select journalTrans where journalTrans.AgreementId == journalTable.AgreementId
    {
        ret = ret && this.checkTrans(journalTrans);
    }

    this.isValid = ret;

    return ret;
}

protected boolean checkTrans(UPSPriceTermJournalTrans _journalTrans)
{
    boolean ret;

    ret = _journalTrans.validateWrite()
        && this.checkJournalLineOverlap_Internal(_journalTrans, _journalTrans.LineNum)
        && this.checkJournalLineOverlap_External(_journalTrans);

    return ret;
}

protected void enableJournal()
{
    ttsbegin;

    journalTable.selectForUpdate(true);
    journalTable.Status = UPSDisabledEnabled::Enabled;

    if (caller)
    {
        caller.postEnable();
    }

    ttscommit;
}

protected void disableJournal()
{
    ttsbegin;

    journalTable.selectForUpdate(true);
    journalTable.Status = UPSDisabledEnabled::Disabled;

    if (caller)
    {
        caller.postDisable();
    }

    ttscommit;
}

private boolean checkJournalLineOverlap_External(UPSPriceTermJournalTrans _journalTrans)
{
    // check journal line with posted price term journal lines.
    UPSPriceTermJournalTable otherJournalTable;
    UPSPriceTermJournalTrans otherJournalTrans;
    UPSPricingRule otherPricingRule;

    UPSPricingRule currentRule = UPSPricingRule::find(_journalTrans.PricingRule);
    UPSPriceTermJournalTable currentJournalTable = UPSPriceTermJournalTable::find(_journalTrans.AgreementId);

    while select otherJournalTrans join otherJournalTable join otherPricingRule
        where otherJournalTrans.AgreementId == otherJournalTable.AgreementId
            && otherJournalTable.AgreementId != this.journalTable.AgreementId
            && otherJournalTable.Status == UPSDisabledEnabled::Enabled
            && otherJournalTable.InventSiteId == currentJournalTable.InventSiteId
            && otherJournalTrans.Code == _journalTrans.Code
            && otherJournalTrans.InventDimId == _journalTrans.InventDimId
            && otherPricingRule.RecId == otherJournalTrans.PricingRule
            && otherPricingRule.PriceAttributeGroup == currentRule.PriceAttributeGroup
    {
        if (currentJournalTable.dateRangesOverlap(otherJournalTable)
            && currentRule.rangeOverlap(UPSPricingRule::find(otherJournalTrans.PricingRule)))
        {
            return checkFailed(strFmt(
                "@UnifiedPricingService:UPSJournalCheckPost_PriceTerm_RangeOverlapExternal",
                _journalTrans.LineNum,
                otherJournalTrans.AgreementId,
                otherJournalTrans.LineNum));
        }
    }

    return true;
}

private boolean checkJournalLineOverlap_Internal(UPSPriceTermJournalTrans _journalTrans, LineNum _startIdx = _journalTrans.LineNum)
{
    // check journal line with lines in the same journal.
    UPSPriceTermJournalTrans otherJournalTrans;
    UPSPricingRule otherPricingRule;

    UPSPricingRule currentRule = UPSPricingRule::find(_journalTrans.PricingRule);

    while select otherJournalTrans join otherPricingRule
        where otherJournalTrans.AgreementId == this.journalTable.AgreementId
            && otherJournalTrans.PricingRule == otherPricingRule.RecId
            && otherPricingRule.PriceAttributeGroup == currentRule.PriceAttributeGroup
            && otherJournalTrans.Code == _journalTrans.Code
            && otherJournalTrans.InventDimId == _journalTrans.InventDimId
            && otherJournalTrans.LineNum > _startIdx
    {
        if (currentRule.rangeOverlap(UPSPricingRule::find(otherJournalTrans.PricingRule)))
        {
            return checkFailed(strFmt(
                "@UnifiedPricingService:UPSJournalCheckPost_PriceTerm_RangeOverlapInternal",
                _journalTrans.LineNum,
                otherJournalTrans.LineNum));
        }
    }

    return true;
}
